import argparse,contextlib,io
p=argparse.ArgumentParser(); p.add_argument('-ss','--shard_size',type=int)
with contextlib.redirect_stderr(io.StringIO()):
 try: p.parse_args(['-ss','1.5'])
 except SystemExit as e: print('fractional shard size exit:',e.code)
for limit in [0,8192*1024**2]:
 shards=[[]]; current=0
 for size in [100,200,300]:
  if current+size>limit and current>0:
   current=0; shards.append([])
  current+=size; shards[-1].append(size)
 print('byte limit:',limit,'shards:',shards)
print('normalized examples:',[x/sum([3,4,5]) for x in [3,4,5]])
